// Code generated by wiregen. DO NOT EDIT.

import { test } from "node:test";
import assert from "node:assert/strict";
import { Telemetry } from "./Telemetry.js";

function makeMessage() {
  const msg = new Telemetry();
  msg.device_id = 3000000000;
  msg.timestamp_us = 12000000000n;
  msg.mode = 5;
  msg.status = 5;
  msg.armed = 1;
  msg.callsign = "skywire";
  msg.battery_mv = 60000;
  return msg;
}

function hex(bytes) {
  return Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join(" ");
}

test("Telemetry RoundTrip", () => {
  const input = makeMessage();
  const wire = input.serialize();
  assert.ok(wire instanceof Uint8Array, "serialize() returns a Uint8Array");
  assert.equal(wire.length, Telemetry.SIZE);
  assert.equal(input.size(), Telemetry.SIZE);
  const output = Telemetry.fromBytes(wire);
  assert.ok(input.equals(output), `round-trip value mismatch\n in ${input}\nout ${output}`);
  assert.equal(JSON.stringify(output), JSON.stringify(input));
  assert.equal(String(output), String(input));
  assert.equal(input.equals(null), false);
  assert.equal(input.equals({}), false);
});

test("Telemetry Fresh", () => {
  assert.equal(hex(new Telemetry().serialize()), hex(new Uint8Array(Telemetry.SIZE)));
  assert.ok(new Telemetry().equals(new Telemetry()));
});

test("Telemetry Equals", () => {
  let msg;
  msg = makeMessage();
  msg.device_id = 0;
  assert.ok(!msg.equals(makeMessage()), "equals ignores device_id");
  msg = makeMessage();
  msg.timestamp_us = 0;
  assert.ok(!msg.equals(makeMessage()), "equals ignores timestamp_us");
  msg = makeMessage();
  msg.mode = 0;
  assert.ok(!msg.equals(makeMessage()), "equals ignores mode");
  msg = makeMessage();
  msg.status = 0;
  assert.ok(!msg.equals(makeMessage()), "equals ignores status");
  msg = makeMessage();
  msg.armed = 0;
  assert.ok(!msg.equals(makeMessage()), "equals ignores armed");
  msg = makeMessage();
  msg.callsign = "";
  assert.ok(!msg.equals(makeMessage()), "equals ignores callsign");
  msg = makeMessage();
  msg.battery_mv = 0;
  assert.ok(!msg.equals(makeMessage()), "equals ignores battery_mv");
});

test("Telemetry ShortBuffer", () => {
  const msg = makeMessage();
  const wire = msg.serialize();
  const shorter = wire.slice(0, wire.length - 1);
  const target = new Telemetry();
  assert.throws(() => target.deserialize(shorter), RangeError);
  assert.ok(target.equals(new Telemetry()), "a failed deserialize changed the message");
  assert.throws(() => target.deserializeFrom(wire, 1), RangeError);
  assert.throws(() => msg.serializeInto(shorter, 0), RangeError);
  assert.throws(() => msg.serializeInto(wire, -1), RangeError);
  assert.throws(() => msg.serializeInto(wire, 0.5), RangeError);
  assert.throws(() => msg.serializeInto(wire, wire.length + 1), RangeError);
  assert.throws(() => msg.serializeInto("not a buffer", 0), TypeError);
});

test("Telemetry Offset", () => {
  const input = makeMessage();
  const wire = input.serialize();
  const backing = new Uint8Array(5 + Telemetry.SIZE + 2);
  const buf = backing.subarray(2);
  assert.equal(input.serializeInto(buf, 3), 3 + Telemetry.SIZE);
  for (let i = 0; i < backing.length; i++) {
    const want = i >= 5 && i < 5 + wire.length ? wire[i - 5] : 0;
    assert.equal(backing[i], want, `serializeInto(buf, 3) differs from serialize() at byte ${i}`);
  }
  const output = new Telemetry();
  assert.equal(output.deserializeFrom(new DataView(backing.buffer, 2), 3), 3 + Telemetry.SIZE);
  assert.ok(input.equals(output), `offset round-trip value mismatch\n in ${input}\nout ${output}`);
  const fromBuffer = new Telemetry();
  assert.equal(fromBuffer.deserializeFrom(backing.buffer, 5), 5 + Telemetry.SIZE);
  assert.ok(input.equals(fromBuffer), "deserializeFrom(ArrayBuffer) differs");
});

test("Telemetry BitfieldSetters", () => {
  const msg = new Telemetry();
  msg.mode = 0x15;
  assert.equal(msg.mode, 5, "mode");
  msg.status = 0xd;
  assert.equal(msg.status, 5, "status");
  msg.armed = 0x3;
  assert.equal(msg.armed, 1, "armed");
});

test("Telemetry SetterWrap", () => {
  const msg = new Telemetry();
  msg.device_id = -1294967296;
  assert.equal(msg.device_id, 3000000000, "device_id");
  msg.timestamp_us = -18446744061709551616n;
  assert.equal(msg.timestamp_us, 12000000000n, "timestamp_us");
  msg.timestamp_us = 7;
  assert.equal(msg.timestamp_us, 7n, "timestamp_us from a Number");
  msg.battery_mv = 125536;
  assert.equal(msg.battery_mv, 60000, "battery_mv");
});

test("Telemetry Strings", () => {
  const msg = new Telemetry();
  msg.callsign = "A";
  assert.equal(msg.callsign.length, 8);
  assert.equal(msg.callsign[0], 65);
  assert.equal(msg.callsignText, "A");
  msg.callsign = "x".repeat(8 + 3);
  assert.equal(msg.callsignText, "x".repeat(8));
  msg.callsign = [1, 2];
  const want = new Uint8Array(8);
  want.set([1, 2].slice(0, 8));
  assert.equal(hex(msg.callsign), hex(want));
  msg.callsign[0] = 9;
  assert.equal(msg.callsign[0], 1, "the getter returns a copy");
  assert.throws(() => { msg.callsign = 5; }, TypeError);
});

function fromHex(text) {
  return Uint8Array.from(text.match(/[0-9a-f]{2}/g) ?? [], (h) => parseInt(h, 16));
}

test("Telemetry Json", () => {
  const input = makeMessage();
  const text = input.toJsonText();
  const got = Telemetry.fromJsonText(text);
  assert.ok(got.equals(input), `JSON round-trip value mismatch\n in ${input}\nout ${got}`);
  assert.equal(got.toJsonText(), text);
  assert.ok(Telemetry.fromJsonText(new TextEncoder().encode(text)).equals(input), "JSON from bytes differs");
});

test("Telemetry JsonEmptyIsDefault", () => {
  assert.ok(Telemetry.fromJsonText("{}").equals(new Telemetry()));
});

