test("Telemetry Xml", () => {
  const input = makeMessage();
  const text = input.toXml();
  const got = Telemetry.fromXml(text);
  assert.ok(got.equals(input), `XML round-trip value mismatch\n in ${input}\nout ${got}`);
  assert.equal(got.toXml(), text);
  assert.ok(Telemetry.fromXml(new TextEncoder().encode(text)).equals(input), "XML from bytes differs");
});

test("Telemetry XmlEmptyIsDefault", () => {
  assert.ok(Telemetry.fromXml("<Telemetry/>").equals(new Telemetry()));
});

