test("Telemetry Bson", () => {
  const input = makeMessage();
  const data = input.toBson();
  assert.ok(data instanceof Uint8Array, "toBson() returns a Uint8Array");
  const got = Telemetry.fromBson(data);
  assert.ok(got.equals(input), `BSON round-trip value mismatch\n in ${input}\nout ${got}`);
  assert.equal(hex(got.toBson()), hex(data));
  assert.ok(Telemetry.fromBson(data.buffer).equals(input), "BSON from an ArrayBuffer differs");
});

test("Telemetry BsonEmptyIsDefault", () => {
  assert.ok(Telemetry.fromBson(Uint8Array.of(5, 0, 0, 0, 0)).equals(new Telemetry()));
});

test("Telemetry BsonLargeUint64_timestamp_us", () => {
  const cases = [
    [2n ** 64n - 1n, "1374696d657374616d705f757300ffffffffffffffff0000000000004030"],
    [2n ** 63n - 1n, "1274696d657374616d705f757300ffffffffffffff7f"],
  ];
  for (const [value, element] of cases) {
    const msg = new Telemetry();
    msg.timestamp_us = value;
    const data = msg.toBson();
    assert.ok(hex(data).includes(hex(fromHex(element))), `timestamp_us = ${value} is not ${element}`);
    assert.ok(Telemetry.fromBson(data).equals(msg), `timestamp_us = ${value} did not read back`);
  }
});

